def longest_subseq_with_diff_one(arr, n=None):
    """Write a function to find the longest subsequence such that the difference between adjacents is one for the given array."""
    if arr is None:
        return 0
    if n is None:
        n = len(arr)
    n = min(n, len(arr))
    if n <= 0:
        return 0

    # best[v] is the length of the longest valid subsequence seen so far
    # whose last element is v. A new element x can extend any such
    # subsequence ending in x - 1 or x + 1, so only those two values
    # need to be considered; this yields an O(n) scan.
    best = {}
    longest = 0
    for i in range(n):
        x = arr[i]
        current = 1 + max(best.get(x - 1, 0), best.get(x + 1, 0))
        if current > best.get(x, 0):
            best[x] = current
        if current > longest:
            longest = current
    return longest
